import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Day06 · 工作流、技能与评测控制台","description":"","frontmatter":{"title":"Day06 · 工作流、技能与评测控制台","outline":false},"headers":[],"relativePath":"log/day-06.md","filePath":"log/day-06.md","lastUpdated":1794305977000}'),o={name:"log/day-06.md"};function l(i,t,c,h,n,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<p>2026-11-09 是 Hearth 把产品入口、任务工作流和评测基础设施同时向前推的一天。当天 89 次提交涉及 445 个文件（+24,538/−1,793）：上午补齐任务追加、Git 工作台、审批预览、PWA 壳和浏览器 E2E，随后把记忆的来源、合并、遗忘和技能生命周期做成可审计记录，最后为评测 case、控制台、运行编排和人工复核建立第一套完整控制面。</p><p>今天的主线不是增加更多概念，而是让已有能力能被日常使用、能被证据复核、能被独立评估。页面可以看起来完整，但任务追加必须受调度约束，技能必须保留权限与代次，评测控制台必须能追到每次运行的真实轨迹。</p><h2 id="交互与任务工作流" tabindex="-1">交互与任务工作流 <a class="header-anchor" href="#交互与任务工作流" aria-label="Permalink to &quot;交互与任务工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>结果</th></tr></thead><tbody><tr><td>任务追加</td><td>运行中可以排队“轮后继续”，或中止当前轮并带补充信息重跑；两种模式都保留任务、产物和既有证据</td></tr><tr><td>Git 工作台</td><td>任务详情展示工作区/分支差异、文件列表、提交、文件预览、PR 与 CI 检查状态，不把终端输出当作最终结果</td></tr><tr><td>审批与工具</td><td>原生执行器在敏感工具前暂停；写文件、命令、联网和截图在必要审批下等待，批准后继续，拒绝后跳过并留下原因</td></tr><tr><td>PWA 与导航</td><td>新增可安装 Manifest、应用图标、离线应用壳、移动底部导航和命令面板；窄屏下任务与审批页面可操作</td></tr><tr><td>截图与首页</td><td>用隔离实例生成 README 与文档站截图，首页改为产品界面、定位和当前状态，不再只讲抽象架构</td></tr></tbody></table><h2 id="记忆、技能与执行输入" tabindex="-1">记忆、技能与执行输入 <a class="header-anchor" href="#记忆、技能与执行输入" aria-label="Permalink to &quot;记忆、技能与执行输入&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>结果</th></tr></thead><tbody><tr><td>记忆来源与信任</td><td>记忆记录来源、可信度、污染状态、敏感度、有效期和用途；召回按范围和信任状态过滤</td></tr><tr><td>记忆合并</td><td>合并只处理可解释的重复与冲突，保留来源链、版本和报告；不把模型摘要当作新事实</td></tr><tr><td>遗忘传播</td><td>遗忘覆盖投影、版本、事件、召回审计、设备同步、派生记忆和合并记录，并留下墓碑防止旧内容复活</td></tr><tr><td>技能生命周期</td><td>技能包支持导出、导入、检查、固定、归档和恢复；采用的方法可转成带权限范围的技能</td></tr><tr><td>自动管理</td><td>终态任务后尽力生成方法候选，过期技能可清理并回退；自动学习仍受开关和证据门槛约束</td></tr></tbody></table><h2 id="目标、完成与评测控制面" tabindex="-1">目标、完成与评测控制面 <a class="header-anchor" href="#目标、完成与评测控制面" aria-label="Permalink to &quot;目标、完成与评测控制面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>结果</th></tr></thead><tbody><tr><td>目标契约</td><td>暴露目标创建、查询、验收条件、预算、截止时间、停止条件和复核策略 API</td></tr><tr><td>完成判定</td><td>新增证据驱动的完成判定，逐项检查验收条件、证据、缺失项和禁止动作；目标型任务关闭前必须有结论</td></tr><tr><td>case 目录</td><td>建立 case 目录加载器、旧清单兼容、邮件/日历/文档/研究/代码/网页/桌面/跨应用样例</td></tr><tr><td>评测控制台</td><td>新增仪表盘、case 目录、实验启动、运行轨迹、人工复核、实验比较和系统状态页面</td></tr><tr><td>评测服务</td><td>评测生命周期持久化、运行编排、人工复核、控制面 API 和 artifact 边界形成代码闭环</td></tr><tr><td>文档</td><td>评测 Agent 工作流、README 首页和产品截图更新；评测 case 与主产品模板仍暂时共用部分结构</td></tr></tbody></table><h2 id="提交记录" tabindex="-1">提交记录 <a class="header-anchor" href="#提交记录" aria-label="Permalink to &quot;提交记录&quot;">​</a></h2><h3 id="_2026-11-09-89-次提交-节选" tabindex="-1">2026-11-09（89 次提交，节选） <a class="header-anchor" href="#_2026-11-09-89-次提交-节选" aria-label="Permalink to &quot;2026-11-09（89 次提交，节选）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>提交</th><th>作者</th><th>修改</th></tr></thead><tbody><tr><td><code>9ec69ce</code></td><td>JasonBuildAI</td><td>重写 README 与文档首页，加入产品截图、当前状态和阅读入口；15 个文件（+1,083/−342）。</td></tr><tr><td><code>7843359</code></td><td>JasonBuildAI</td><td>补齐任务轮后追加、中止重跑、工具审批、Git 工作台、PWA 壳、命令面板和窄屏交互；47 个文件（+4,380/−100）。</td></tr><tr><td><code>149e7c9</code></td><td>JasonBuildAI</td><td>新增隔离数据目录的可重复浏览器 E2E，覆盖聊天、任务、设置、密钥掩码和恢复路径；6 个文件（+533/−6）。</td></tr><tr><td><code>d01f61f</code></td><td>JasonBuildAI</td><td>为记忆持久化来源、可信度、污染状态、敏感度和有效期；4 个文件（+229/−22）。</td></tr><tr><td><code>3ff7889</code></td><td>JasonBuildAI</td><td>新增可审计的记忆合并流程，保留来源、版本、分组理由和报告；7 个文件（+565/−22）。</td></tr><tr><td><code>be07437</code></td><td>JasonBuildAI</td><td>遗忘传播到投影、版本、事件、同步和派生记忆，并写入墓碑；6 个文件（+396/−52）。</td></tr><tr><td><code>0d06a3a</code></td><td>JasonBuildAI</td><td>持久化技能生命周期并暴露 API：导出、导入、检查、固定、归档和恢复；6 个文件（+632/−9）。</td></tr><tr><td><code>4e46792</code></td><td>JasonBuildAI</td><td>把已采用的方法导出为带权限范围的技能包；3 个文件（+490）。</td></tr><tr><td><code>85d9886</code></td><td>JasonBuildAI</td><td>新增 case 目录加载器与旧清单兼容，覆盖多类真实任务；33 个文件（+740）。</td></tr><tr><td><code>ce57f05</code></td><td>JasonBuildAI</td><td>评测服务编排运行和人工复核，保存生命周期、失败样本和复核动作；3 个文件（+935/−1）。</td></tr><tr><td><code>2c415d9</code></td><td>JasonBuildAI</td><td>新增证据驱动的完成判定，检查验收条件、证据、缺失项和禁止动作；2 个文件（+413）。</td></tr><tr><td><code>c828e5f</code></td><td>JasonBuildAI</td><td>暴露目标契约 API，支持创建、查询和更新验收条件、预算与复核策略；1 个文件（+134/−3）。</td></tr><tr><td><code>aa93b56</code></td><td>JasonBuildAI</td><td>目标型任务关闭前必须取得完成结论，不能把执行器结束当作完成；3 个文件（+104）。</td></tr></tbody></table><h2 id="边界与下一步" tabindex="-1">边界与下一步 <a class="header-anchor" href="#边界与下一步" aria-label="Permalink to &quot;边界与下一步&quot;">​</a></h2><ul><li>PWA 壳、移动底部导航和离线应用壳只是入口，不是手机配对、系统推送或远程接管；这些仍未验收。</li><li>任务追加按轮边界生效，不是向正在生成的 token 流实时注入；Git 工作台依赖真实仓库和凭据，未做多仓库压力验收。</li><li>记忆合并、遗忘传播和技能生命周期已有自动测试，但没有真实长期个人数据、错误记忆演练和生产方法对照。</li><li>完成判定已接入目标和调度，但主观质量、真实业务影响和跨设备交接仍需人工验收。</li><li>评测控制台、case 目录和服务形成代码闭环，但真实实验尚未运行；次日这些内容会迁到独立仓库，主仓库只保留桥接。</li><li>阶段二至六的真实账户、真实设备、手机入口和长期运行验收没有变化。</li></ul>',13)])])}const A=d(o,[["render",l]]);export{u as __pageData,A as default};
